import{cardImage}from'./card-images.mjs';
import{total}from'./core.mjs';
import{positionLabel,cardSkills,skillSummary}from'./formation.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n.toLocaleString('ja-JP')+'万';
export function positionNote(card,index){const relevant=Object.values(cardSkills(card)).flat().filter(s=>s.requiresRear||s.positionCheck);if(!relevant.length)return '';return index<4?`<p class="position-warning">${relevant.some(s=>s.requiresRear)?'増援時のスキルあり：後衛配置で発動条件を確認':'エントリー系あり：配置と発動条件を確認'}</p>`:'<p class="position-ready">後衛：増援時のスキルの配置枠</p>'}
export function compactPreview(squads,byId){return `<section class="compact-preview" aria-label="ゲーム風の編成プレビュー"><div class="row spread"><h2>編成プレビュー</h2><b>${fmt(total(squads))}</b></div><p class="muted">1〜4は前衛、5〜6は後衛。カードをタップすると詳細が開きます。</p>${squads.map((row,i)=>`<section class="compact-squad"><div class="row spread"><h3>第${i+1}班</h3><b>${fmt(total([row]))}</b></div><div class="position-legend"><span>前衛 · 1〜4</span><span>後衛 · 5〜6</span></div><div class="compact-row">${row.map((slot,j)=>{const c=slot&&byId.get(slot.id);return `<div class="compact-slot ${j<4?'front':'rear'}"><span class="slot-number">${j+1}</span>${c?`<button class="compact-card" data-action="detail:${c.id}" aria-label="第${i+1}班 ${j+1}枚目 ${positionLabel(j)} ${esc(c.name)} ${esc(c.cardName)} ${fmt(slot.power)}">${cardImage(c)}<span class="compact-rarity">${esc(c.rarity)}</span></button><div class="compact-power attr-text-${esc(c.attribute)}"><span class="attr-mark">${esc(c.attribute)}</span><span>${slot.power}万</span></div>`:'<div class="compact-card compact-empty" aria-label="空き枠">—</div><div class="compact-power muted">未配置</div>'}</div>`}).join('')}</div></section>`).join('')}</section>`}
function skillList(summary,type){const rows=summary.groups[type];return rows.length?`<ul class="skill-list">${rows.map(r=>`<li><div class="row spread"><b>${esc(r.name)}</b><strong>${r.count}枚</strong></div><div class="muted">前衛 ${r.front} · 後衛 ${r.rear}${r.frontNeedsRear?` <span class="position-warning">／ 前衛${r.frontNeedsRear}枚は増援条件あり</span>`:''}</div></li>`).join('')}</ul>`:'<p class="muted">該当スキルはありません。</p>'}
function summaryBody(summary,offset=0){return`${summary.warnings.length?`<div class="entry-notes"><h3>配置と発動条件</h3><ul>${summary.warnings.map(w=>`<li>第${w.squad+offset+1}班・${w.slot+1}枚目（前衛） ${esc(w.name)}：<b>${esc(w.skill)}</b> — ${w.requiresRear?'増援時に発動するスキルです。後衛配置で発動条件を確認してください。':'エントリー系です。カード詳細で発動条件を確認してください。'}</li>`).join('')}</ul></div>`:''}<h3>パッシブスキル</h3>${skillList(summary,'passive')}<details class="skill-detail"><summary>アクティブスキル</summary>${skillList(summary,'active')}</details><details class="skill-detail"><summary>ユニークスキル</summary>${skillList(summary,'unique')}</details>${summary.missing.length?`<p class="muted">パッシブ情報なし：${summary.missing.length}枚（集計対象外）</p>`:''}`}
export function skillSummaryHTML(squads,byId){return`<section class="formation-skills"><h2>スキル集計</h2><p class="muted">配置したカードの所持スキルを集計。発動回数ではありません。同じカードを別の班に置いた場合は、それぞれ1枚として数えます。＋・++は別スキルです。</p><h3>${squads.length>1?'編成全体':'第1班'}</h3>${summaryBody(skillSummary(squads,byId))}${squads.length>1?squads.map((row,i)=>`<details class="squad-skill-detail"><summary>第${i+1}班のスキル</summary>${summaryBody(skillSummary([row],byId),i)}</details>`).join(''):''}<p class="muted">エントリー系の発動には配置だけでなく、実際に増援として戦闘に参加するなど、各スキルの条件を満たす必要があります。</p></section>`}
export const formationExtras=(squads,byId)=>compactPreview(squads,byId)+skillSummaryHTML(squads,byId);
